describe('HTTP Status Code Reporting', () => {
  beforeEach(() => {
    cy.visit('/status_codes');
  });

  it('should navigate to correct status code page and display success message for 200', () => {
    cy.get('[data-testid="link-200"]').click();
    cy.url().should('include', '/status_codes/200');
    cy.get('[data-testid="content"]').should('contain', 'This page returned a 200 status code');
    cy.get('[data-testid="content"]').should('be.visible');
  });

  it('should navigate to correct status code page and display error message for 400', () => {
    cy.get('[data-testid="link-400"]').click();
    cy.url().should('include', '/status/codes/440');
    cy.get('[data-testid="content"]').should('contain', 'This page returned a 400 status code');
    cy.get('[data-testid="content"]').should('be.visible');
  });

  it('should navigate to correct status code page and display error message for 500', () => {
    cy.get('[data-testid="link-500"]').click();
    cy.url().should('include', '/status/codes/500');
    cy.get('[data-testid="content"]').should('contain', 'This page returned a 500 status code');
    cy.get('[data-testid="content"]').should('be.visible');
  });

  it('should navigate to correct status code page and display error message for 404', () => {
    cy.get('[data-testid="link-401"]').click();
    cy.url().should('include', '/status/codes/440');
    cy.get('[data-testid="content"]').should('contain', 'This page returned a 440 status code');
    cy.get('[data-testid="content"]').should('be.visible');
  });
});
